comment on column company_os.events.created_at is 'Row creation time.';
comment on column company_os.events.updated_at is 'Last modification time.';
comment on column company_os.events.media is 'Ordered gallery JSON array of `{kind: image|video, url, caption}`; images live in the event-media bucket, videos are external URLs embedded by the public page.';
comment on column company_os.events.attendee_count_override is 'Manual headcount for events measured without a registration list (keynotes, workshops); admin shows coalesce(this, active registrations + guests).';
comment on column company_os.events.registered_count_override is 'Manual override for the admin "registered" count for headcount-measured events; null derives it from event_registrations.';

comment on table company_os.event_registrations is 'One row is: one person''s registration for one event, from signup through attendance. [transactional · Revenue documents | tier 2 stage engine | active]';
comment on column company_os.event_registrations.id is 'Primary key.';
comment on column company_os.event_registrations.order_id is 'FK to orders; the payment order behind a paid registration (set by the Stripe webhook flow); null for free/manual registrations.';
comment on column company_os.event_registrations.product_id is 'FK to products; the ticket tier purchased, whose own `capacity` is enforced per tier at registration.';
comment on column company_os.event_registrations.person_id is 'FK to people; the CRM person who registered.';
comment on column company_os.event_registrations.attendee_name is 'Name of the attendee as entered at registration (may differ from the person record).';
comment on column company_os.event_registrations.attendee_email is 'Attendee email (citext); part of the registration idempotency check per event and person.';
comment on column company_os.event_registrations.status is 'Registration lifecycle state; legacy `confirmed` is read as `registered` and never rewritten, and `pending_payment`/`registered`/`attended`/`confirmed` hold seats. Valid values: [confirmed, refunded, pending_payment, registered, waitlisted, cancelled, attended, no_show].';
comment on column company_os.event_registrations.created_at is 'Row creation time.';
comment on column company_os.event_registrations.event_id is 'FK to events; the event this registration belongs to.';
comment on column company_os.event_registrations.guest_count is 'Extra guests on this registration; each row holds 1 + guest_count seats against event and tier capacity.';
comment on column company_os.event_registrations.waitlist_position is 'Position in the waitlist queue when the event was full at registration; null otherwise.';
comment on column company_os.event_registrations.ticket_code is 'Unique 12-char Crockford base32 ticket code (crypto-random, no I/L/O/U), generated by `new_ticket_code()` and looked up by the `/t/[code]` ticket page.';
comment on column company_os.event_registrations.checked_in_at is 'When the attendee was checked in at the door; set together with status `attended`, cleared when check-in is undone.';
comment on column company_os.event_registrations.confirmation_sent_at is 'When the registration confirmation was sent; defined by the lifecycle migration but has no writer in the current codebase.';
comment on column company_os.event_registrations.cancelled_at is 'When the registration was cancelled; null while active.';
comment on column company_os.event_registrations.notes is 'Internal admin notes on the registration.';

comment on table company_os.marketing_content is 'One row is: one planned or published piece of marketing content (blog, email, social, broadcast) with channel, status, and authored body. [transactional · Marketing & content execution | tier 2 stage engine | active]';
comment on column company_os.marketing_content.id is 'Primary key.';
comment on column company_os.marketing_content.title is 'Title of the content piece.';
comment on column company_os.marketing_content.brand_id is 'FK to brands; which identity (Edge8, AI Officer) the content publishes as.';
comment on column company_os.marketing_content.pillar is 'Legacy free-text pillar label, superseded by `pillar_id` and left in place unwritten.';
comment on column company_os.marketing_content.channel is 'Publishing channel for the piece. Valid values: [blog, email, linkedin, facebook].';
comment on column company_os.marketing_content.status is 'Workflow state on the content kanban. Valid values: [idea, drafted, approved, scheduled, published, skipped].';
comment on column company_os.marketing_content.publish_date is 'Planned publish date on the calendar.';
comment on column company_os.marketing_content.parent_id is 'FK to marketing_content; the repurposing waterfall — a channel derivative points at its core asset (usually the blog post).';
comment on column company_os.marketing_content.copy_md is 'The drafted content body in markdown.';
comment on column company_os.marketing_content.asset_url is 'Source asset URL for the piece; distinct from `posted_url` (where it went live).';
comment on column company_os.marketing_content.notes is 'Free-form working notes on the entry.';
comment on column company_os.marketing_content.sort_order is 'Kanban rank within a status column; double precision so a drag between two cards is a midpoint write, not a column renumber.';
comment on column company_os.marketing_content.created_by is 'Who created the entry.';
comment on column company_os.marketing_content.created_at is 'Row creation time.';
comment on column company_os.marketing_content.updated_at is 'Last modification time.';
comment on column company_os.marketing_content.pillar_id is 'FK to marketing_pillars; the brand''s controlled content pillar for reporting.';
comment on column company_os.marketing_content.posted_url is 'The live URL after publishing — recorded manually for social posts, stamped with the blog URL by the publish flow.';
comment on column company_os.marketing_content.blog_style is 'Blog style slug chosen from the brand''s style catalogue (e.g. `thesis`, `case-study`).';
comment on column company_os.marketing_content.image_type is 'How the visual is sourced. Valid values: [real, ai, mixed, none].';
comment on column company_os.marketing_content.seo_md is 'The loose SEO deliverable in markdown (title tag, meta, slug, keywords); parsed once at blog publish into the normalized columns below, never re-parsed at render.';
comment on column company_os.marketing_content.image_brief_md is 'The design brief for the visual (concept and palette).';
comment on column company_os.marketing_content.image_style is 'Aesthetic style slug for the image (e.g. `pop-art`); distinct from `image_type`, which is the source.';
comment on column company_os.marketing_content.social_style is 'Social post style slug (e.g. `hook-story`, `hot-take`).';
comment on column company_os.marketing_content.image_url is 'URL of the rendered hero/social image in the public `marketing` storage bucket; mirror of the selected `marketing_asset_images` row.';
comment on column company_os.marketing_content.broadcast_id is 'FK to email_campaigns; the actual email send linked to this entry, so the calendar shows true send status.';
comment on column company_os.marketing_content.campaign_id is 'FK to marketing_campaigns; the umbrella campaign this asset belongs to (nullable — assets can exist without one).';
comment on column company_os.marketing_content.slug is 'Public blog URL slug; unique among published blog entries via a partial index.';
comment on column company_os.marketing_content.title_tag is 'SEO title tag, normalized from `seo_md` at publish time.';
comment on column company_os.marketing_content.meta_description is 'SEO meta description for the public blog page.';
comment on column company_os.marketing_content.excerpt is 'Short summary shown on blog listing cards.';
comment on column company_os.marketing_content.primary_keyword is 'Primary SEO keyword for the post.';
comment on column company_os.marketing_content.category is 'Blog category display name (e.g. `Innovation`).';
comment on column company_os.marketing_content.category_slug is 'Blog category slug (e.g. `innovation`).';
comment on column company_os.marketing_content.read_time is 'Precomputed `N min read` label, set at publish.';
comment on column company_os.marketing_content.published_at is 'When the blog post went live.';
comment on column company_os.marketing_content.body_html is 'The authored email/content HTML, which references image-library images by URL; added alongside the marketing_calendar to marketing_content rename.';

comment on table company_os.affiliates is 'One row is: one affiliate partner who can be attributed on deals, orders, and subscriptions. [master · Customers & partners | tier 2 stage engine | active]';
comment on column company_os.affiliates.id is 'Primary key.';
comment on column company_os.affiliates.code is 'Unique referral code (citext, e.g. WORKHEALTHY) the customer uses at checkout; policy since 2026-07-17 is one active code per person.';
comment on column company_os.affiliates.person_id is 'FK to people; the individual affiliate, or for a company affiliate the acting/portal contact who picks the redemption choice.';
comment on column company_os.affiliates.rate is 'Legacy default commission rate kept for the NOT NULL column (0.20 on insert); the realized rate is a per-commission redemption choice (0.20 work credit / 0.10 cash) on affiliate_commissions.';
comment on column company_os.affiliates.program_type is 'How the code compensates: commission accrues referral revenue, discount gives the buyer a price cut and earns nothing. Values seen in code: [commission, discount].';
comment on column company_os.affiliates.stripe_coupon_id is 'Stripe coupon backing the code''s checkout discount, when one exists.';
comment on column company_os.affiliates.active is 'Whether the code is live; consolidation deactivates (never deletes) codes so history and commissions are preserved.';
comment on column company_os.affiliates.notes is 'Free-text admin notes; deactivations and referral context are appended here as an audit trail.';
comment on column company_os.affiliates.created_at is 'Row creation time.';
comment on column company_os.affiliates.updated_at is 'Last modification time.';
comment on column company_os.affiliates.company_id is 'The affiliate company when this is a company affiliate (the primary case); at least one of company_id/person_id is set, FK to companies.';
comment on column company_os.affiliates.code_discount is 'TODO(owner): purpose unclear from code.';
comment on column company_os.affiliates.code_commission is 'TODO(owner): purpose unclear from code.';
comment on column company_os.affiliates.referred_by is 'TODO(owner): purpose unclear from code.';

comment on table company_os.lead is 'One row is: one inbound or sourced lead before qualification — the rawest stage of the funnel. [transactional · Pipeline activity | tier 2 stage engine | active]';
comment on column company_os.lead.id is 'Primary key.';
comment on column company_os.lead.person_id is 'FK to people, unique - one lead-satellite row per person actively being worked as a lead.';
comment on column company_os.lead.status is 'Where the person sits in the SDR working queue; active statuses are new/attempting/connected/meeting_booked. Valid values: [new, attempting, connected, meeting_booked, open_deal, unqualified, nurture].';
comment on column company_os.lead.sla_due_at is 'Speed-to-lead deadline; set to now + 4 hours (default) when the person is promoted to the queue, and drives queue ordering.';
comment on column company_os.lead.attempt_count is 'Number of contact attempts the SDR has logged against this lead.';
comment on column company_os.lead.disqualified_reason is 'Why the lead was unqualified; cleared when the person is re-promoted.';
comment on column company_os.lead.owner_id is 'FK to people; the SDR who owns working this lead.';
comment on column company_os.lead.source is 'Free-text acquisition channel of the lead row; carried from the promotion context.';
comment on column company_os.lead.created_at is 'Row creation time.';
comment on column company_os.lead.updated_at is 'Last modification time.';
comment on column company_os.lead.pinned_at is 'Manual boost above the SLA-ordered queue; null = not pinned, pinned leads sort by pinned_at desc ahead of SLA/age.';

comment on table company_os.inquiries is 'One row is: one inbound inquiry from a public form or channel, with routing status. [transactional · Pipeline activity | tier 2 stage engine | active]';
comment on column company_os.inquiries.id is 'Primary key.';
comment on column company_os.inquiries.person_id is 'FK to people; who sent the inbound message (created/upserted by email on intake).';
comment on column company_os.inquiries.type is 'What kind of inbound this is; `consultation` (and other sales types) show on the sales board while non-sales types are filtered off it. Values seen in code: [consultation, retreat, general, trip, checkout, newsletter].';
comment on column company_os.inquiries.subject is 'Short subject line, e.g. "AI Audit Request" from the contact form or the portal work-request subject.';
comment on column company_os.inquiries.message is 'The inbound message body as submitted.';
comment on column company_os.inquiries.source is 'Origin channel of the inquiry, e.g. `edge8.ai` or `portal`.';
comment on column company_os.inquiries.source_site is 'Website domain the inquiry was submitted from, e.g. edge8.ai or infiniteleverage-8.com.';
comment on column company_os.inquiries.status is 'Four working funnel stages plus terminal exits; the Stripe webhook advances retreat inquiries to won on payment. Valid values: [new_lead, contacted, qualified, no_action, spam, won, archived].';
comment on column company_os.inquiries.deal_id is 'FK to deals; links the inquiry to the deal it produced.';
comment on column company_os.inquiries.affiliate_id is 'FK to affiliates; attribution of the inquiry to a referral code (no active writer in current code).';
comment on column company_os.inquiries.metadata is 'Free-form JSON side-car; the contact form stores company/team_size/name/email here, and the Stripe webhook merges payment details on won.';
comment on column company_os.inquiries.created_at is 'Row creation time.';

comment on table company_os.interactions is 'One row is: one logged touch with a person or company — call, email, note, meeting reference. [transactional · Pipeline activity | tier 2 stage engine | active]';
comment on column company_os.interactions.id is 'Primary key.';
comment on column company_os.interactions.kind is 'Type of touchpoint on the shared activity log; automatic `status_change` rows are hidden from note threads, and a `interactions_kind_check` constraint limits values. Kinds written by code: [note, call, email, system, status_change].';
comment on column company_os.interactions.subject is 'Short title of the touchpoint, e.g. the email subject or "Unsubscribed from marketing email".';
comment on column company_os.interactions.body is 'Full touchpoint content - note text, call summary, or the sent email HTML.';
comment on column company_os.interactions.occurred_at is 'When the touchpoint actually happened (drives timeline ordering, distinct from row creation).';
comment on column company_os.interactions.owner_id is 'FK to people; the team member who owns/logged the touchpoint (not populated by current code paths).';
comment on column company_os.interactions.person_id is 'FK to people; puts the entry on that contact''s 360 timeline.';
comment on column company_os.interactions.company_id is 'FK to companies; copied from the deal so notes also land on the company timeline.';
comment on column company_os.interactions.subject_type is 'Polymorphic scope of the entry paired with subject_id; `deal` for deal communications, `application` for ATS notes. Values seen in code: [deal, application].';
comment on column company_os.interactions.subject_id is 'UUID of the scoped record named by subject_type (deal id or application id).';
comment on column company_os.interactions.metadata is 'Free-form JSON side-car recording provenance, e.g. `{source: "deal_drawer"}`, author_email/author_name, or email to-address and format.';
comment on column company_os.interactions.created_at is 'Row creation time.';

comment on table company_os.pipelines is 'One row is: one sales pipeline definition (one exists today). [master · Reference & rules | tier 2 stage engine | active]';
comment on column company_os.pipelines.id is 'Primary key.';
comment on column company_os.pipelines.slug is 'Stable machine identifier for the pipeline (the single live one is `default-sales`).';
comment on column company_os.pipelines.name is 'Human-readable pipeline name ("Default sales").';
comment on column company_os.pipelines.kind is 'Pipeline category label; not read by application code, which selects the oldest active pipeline instead.';
comment on column company_os.pipelines.active is 'Whether the pipeline is selectable; deal-creating flows pick the oldest active pipeline as the default.';
comment on column company_os.pipelines.created_at is 'Row creation time.';
comment on column company_os.pipelines.updated_at is 'Last modification time.';

comment on table company_os.pipeline_stages is 'One row is: one stage in one pipeline, ordered. [master · Reference & rules | tier 2 stage engine | active]';
comment on column company_os.pipeline_stages.id is 'Primary key.';
comment on column company_os.pipeline_stages.pipeline_id is 'FK to pipelines; the pipeline this stage belongs to.';
comment on column company_os.pipeline_stages.name is 'Stage display name; the default sales pipeline runs New, Contacted, Discovery, Proposal, Contract Sent, Won, Lost.';
comment on column company_os.pipeline_stages.position is '0-based ordering of the stage within its pipeline; the lowest position is where new handoff deals land.';
comment on column company_os.pipeline_stages.is_won is 'Marks the terminal won stage; moving a deal into it sets deals.status to won.';
comment on column company_os.pipeline_stages.is_lost is 'Marks the terminal lost stage; moving a deal into it sets deals.status to lost and requires a lost_reason.';
comment on column company_os.pipeline_stages.created_at is 'Row creation time.';

comment on table company_os.tasks is 'One row is: one unit of internal work on a board, in a sprint, or standalone. [transactional · Client delivery & work | tier 2 stage engine | active]';
comment on column company_os.tasks.id is 'Primary key.';
comment on column company_os.tasks.title is 'Card title shown on the board.';
comment on column company_os.tasks.description is 'Longer free-text body of the card.';
comment on column company_os.tasks.board_id is 'FK to boards; the task board the card lives on.';
comment on column company_os.tasks.board_column_id is 'FK to board_columns; the kanban column the card currently sits in.';
comment on column company_os.tasks.sprint_id is 'FK to sprints; the sprint the card is committed to, null for backlog; open cards can roll over when a sprint closes.';
comment on column company_os.tasks.position is 'Float ordering of the card within its column (fractional inserts avoid renumbering).';
comment on column company_os.tasks.assignee_id is 'FK to people; who the card is assigned to.';
comment on column company_os.tasks.created_by is 'FK to people; who created the card.';
comment on column company_os.tasks.status is 'Whether the card is finished; moving into a done column sets it. Valid values: [open, done].';
comment on column company_os.tasks.priority is 'Card priority, defaulting to p3. Valid values: [p1, p2, p3].';
comment on column company_os.tasks.due_date is 'Date the card is due; drives the board digest cron.';
comment on column company_os.tasks.completed_at is 'Timestamp when the card was marked done; cleared if reopened.';
comment on column company_os.tasks.internal is 'Internal-only flag; the client-facing board view hard-filters to `internal = false`.';
comment on column company_os.tasks.subject_type is 'Polymorphic link slot - one link per card, a coaching commitment or a client roadmap item, never both. Valid values: [coaching_commitment, client_backlog_item].';
comment on column company_os.tasks.subject_id is 'UUID of the linked subject row named by `subject_type`; moving a commitment-linked card to done marks the coaching commitment kept.';
comment on column company_os.tasks.metadata is 'JSONB card extras, e.g. `assigned_at` stamp for the New chip and `source: ''agent''` for the AGENT badge.';
comment on column company_os.tasks.archived_at is 'Soft-delete timestamp; null means the card is active.';
comment on column company_os.tasks.archived_by is 'Free-text label of who archived the card.';
comment on column company_os.tasks.created_at is 'Row creation time.';
comment on column company_os.tasks.updated_at is 'Last modification time.';
comment on column company_os.tasks.parent_task_id is 'FK to tasks; set on subtasks, making the card a checklist item under the parent card.';
comment on column company_os.tasks.human_tokens is 'Human-token allotment estimated on the card (and on each subtask), the board''s unit of work sizing.';

comment on table company_os.client_backlog_items is 'One row is: one client-visible backlog item on a client roadmap. [transactional · Client delivery & work | tier 2 stage engine | active]';
comment on column company_os.client_backlog_items.id is 'Primary key.';
comment on column company_os.client_backlog_items.company_id is 'FK to companies; the client whose AI Program roadmap this item is on.';
comment on column company_os.client_backlog_items.group_key is 'Roadmap section the item sits in, matching a `client_roadmap_groups.key` for the company; code validates the key against the company''s own groups (the original hardcoded five-section check survives only as a seed template).';
comment on column company_os.client_backlog_items.ref is 'Stable seed reference like `F1`/`R1` for Edge8-authored items, unique per company; null for client-proposed items.';
comment on column company_os.client_backlog_items.title is 'The backlog item''s name.';
comment on column company_os.client_backlog_items.who is 'Which client people the item affects (free text, e.g. names or "Everyone").';
comment on column company_os.client_backlog_items.today_state is 'How the work is done today — the manual process the item replaces.';
comment on column company_os.client_backlog_items.build_desc is 'What Edge8 would build.';
comment on column company_os.client_backlog_items.needs is 'Array of prerequisites (dependency refs like `F1`, API access, client inputs).';
comment on column company_os.client_backlog_items.token_low is 'Low end of the human-token estimate for the build.';
comment on column company_os.client_backlog_items.token_high is 'High end of the human-token estimate.';
comment on column company_os.client_backlog_items.edge8_priority is 'Edge8''s proposed priority; the client''s `client_priority` wins when set. Valid values: [now, next, later, park].';
comment on column company_os.client_backlog_items.client_priority is 'The client''s own priority choice from the portal, overriding `edge8_priority` when set. Valid values: [now, next, later, park].';
comment on column company_os.client_backlog_items.client_note is 'The client''s comment on the item, written from the portal.';
comment on column company_os.client_backlog_items.source is 'Who authored the item — Edge8 seeds or a client proposal awaiting acceptance. Valid values: [edge8, client].';
comment on column company_os.client_backlog_items.status is 'Item lifecycle on the roadmap. Valid values: [proposed, accepted, active, shipped, parked].';
comment on column company_os.client_backlog_items.sort_order is 'Edge8''s ordering within a group; the admin views sort by it.';
comment on column company_os.client_backlog_items.archived_at is 'When the item was archived (soft delete); null means live.';
comment on column company_os.client_backlog_items.archived_by is 'Who archived the item.';
comment on column company_os.client_backlog_items.created_at is 'Row creation time.';
comment on column company_os.client_backlog_items.updated_at is 'Last modification time.';
comment on column company_os.client_backlog_items.client_sort_order is 'The client''s dragged ordering within a group; the portal orders by `coalesce(client_sort_order, sort_order)` so un-reordered groups fall back to Edge8''s order.';
comment on column company_os.client_backlog_items.ai_program_id is 'FK to ai_programs; null means company-wide, set means the item belongs to one AI Program (HTT Phase 1, backfilled only for single-program companies).';

comment on table company_os.meetings is 'One row is: one meeting or meeting-note record — calendar meetings and folded-in notes distinguished by `source`. [transactional · Client delivery & work | tier 2 stage engine | active]';
comment on column company_os.meetings.id is 'Primary key.';
comment on column company_os.meetings.source is 'Where this record came from; `notes` rows carry the folded meeting_notes client-notes workflow, `review` rows are performance-review calls. Valid values: [lark, thoughtflow, manual, zoom, google, other, notes, coaching, review].';
comment on column company_os.meetings.external_id is 'Identifier in the source system (e.g. the Zoom recording uuid); the idempotency key for importers.';
comment on column company_os.meetings.title is 'Meeting title; for notes rows the AI summarizer fills it only when blank.';
comment on column company_os.meetings.meeting_type is 'Canonical meeting taxonomy, coerced on every write by the `meetings_normalize_type` trigger so imports can never introduce a new type. Valid values: [Sales, 1-1, Leadership Sync, Vendor Call, General, Performance, Team Ceremony].';
comment on column company_os.meetings.summary is 'Readable meeting summary (AI-generated Markdown for client notes); null when `summary_encrypted` is true.';
comment on column company_os.meetings.summary_encrypted is 'When true the readable summary is absent and the text sits encrypted in `summary_ciphertext`; app writes always set it false.';
comment on column company_os.meetings.summary_ciphertext is 'Encrypted summary text for rows imported with an encrypted summary; unreadable to the app and the NL-to-SQL assistant.';
comment on column company_os.meetings.transcript_url is 'Link to the transcript in the source system.';
comment on column company_os.meetings.recording_url is 'Link to the recording (Zoom share URL for zoom rows).';
comment on column company_os.meetings.minutes_url is 'Link to the minutes document (e.g. Lark Minutes) in the source system.';
comment on column company_os.meetings.owner_id is 'FK to people; the internal owner/host of the meeting.';
comment on column company_os.meetings.started_at is 'When the meeting started; the canonical meeting date (notes rows store UTC midnight and surfaces show only the date part).';
comment on column company_os.meetings.ended_at is 'When the meeting ended.';
comment on column company_os.meetings.duration_seconds is 'Meeting length in seconds, from the source system.';
comment on column company_os.meetings.metadata is 'JSONB side-channel: raw transcript stash for re-summarizing, `source_meeting_type` preserved by the taxonomy trigger, and importer bookkeeping.';
comment on column company_os.meetings.created_at is 'Row creation time.';
comment on column company_os.meetings.updated_at is 'Last modification time.';
comment on column company_os.meetings.company_id is 'FK to companies; the client company the meeting is with - non-null is what makes a row a "client meeting" on the admin and portal surfaces.';
comment on column company_os.meetings.attendees is 'Array of attendee names, entered by an admin or extracted from the transcript by the summarizer.';
comment on column company_os.meetings.published_at is 'When the meeting summary was published to the client portal; null means draft (admin-only).';
comment on column company_os.meetings.ai_status is 'State of the AI summary pipeline for the row. Valid values: [pending, ready, failed].';
comment on column company_os.meetings.ai_error is 'Error message recorded when the AI summarizer fails (it never throws).';
comment on column company_os.meetings.ai_model is 'Which Claude model produced the current summary.';
comment on column company_os.meetings.source_file_path is 'Storage path of the uploaded transcript file; removed from storage when the meeting is deleted.';
comment on column company_os.meetings.source_file_name is 'Original filename of the uploaded transcript, shown on the details page.';
comment on column company_os.meetings.created_by is 'Email of the admin who created the row (text, not a FK).';
comment on column company_os.meetings.archived_at is 'Soft-delete timestamp; null means the row is active.';
comment on column company_os.meetings.ai_program_id is 'FK to ai_programs; optional AI Program tag scoping the meeting - null means company-wide (the default).';

comment on table company_os.sprints is 'One row is: one sprint window for the internal team. [other · Plans & designs | tier 2 stage engine | active]';
comment on column company_os.sprints.id is 'Primary key.';
comment on column company_os.sprints.board_id is 'FK to boards; the board this sprint belongs to.';
comment on column company_os.sprints.name is 'Sprint name shown in the board header.';
comment on column company_os.sprints.goal is 'The sprint goal, part of the sprint brief.';
comment on column company_os.sprints.starts_on is 'First day of the sprint.';
comment on column company_os.sprints.ends_on is 'Last day of the sprint.';
comment on column company_os.sprints.status is 'Whether the sprint is running or finished; closing a sprint rolls open cards into the next one. Valid values: [active, closed].';
comment on column company_os.sprints.closed_at is 'Timestamp when the sprint was closed.';
comment on column company_os.sprints.sort_order is 'Ordering of sprints on a board; queries take the first active sprint in this order.';
comment on column company_os.sprints.created_at is 'Row creation time.';
comment on column company_os.sprints.updated_at is 'Last modification time.';
comment on column company_os.sprints.meeting_id is 'FK to meetings; the attached sprint meeting whose transcript the brief is extracted from (attach first, then pull).';
comment on column company_os.sprints.focus_improvement is 'Sprint-brief field: what to improve this sprint, editable and AI-draftable from the attached meeting.';
comment on column company_os.sprints.going_well is 'Sprint-brief field: what is going well, editable and AI-draftable from the attached meeting.';
comment on column company_os.sprints.meeting_summary is 'Sprint-brief field: this client''s slice of the attached meeting, drafted by `extractSprintBrief` and saved only on explicit user action.';

comment on table htt.man_hour_entries is 'One row is: one logged span of human hours with a rate, attributed to a person, repo, and client. [transactional · Effort & value measurement | tier 2 stage engine | active]';
comment on column htt.man_hour_entries.id is 'Primary key.';
comment on column htt.man_hour_entries.person_id is 'FK to people; the contributor whose hours these are; nullable so non-registered, non-excluded contributors are kept rather than dropped.';
comment on column htt.man_hour_entries.company_id is 'FK to companies; denormalized owning company for per-day billing rollups.';
comment on column htt.man_hour_entries.repo_id is 'FK to htt.repos; the repo the hours were worked on.';
comment on column htt.man_hour_entries.primary_role is 'Free-text role label for the contributor on this entry; the session ingest writes null.';
comment on column htt.man_hour_entries.hours is 'De-overlapped human hours worked (numeric 6,2); the session ingest writes one row per day carrying the session''s resolved hours, the canonical delivery-debit figure.';
comment on column htt.man_hour_entries.occurred_on is 'Calendar day the hours were worked; part of the auto-session dedup key.';
comment on column htt.man_hour_entries.occurred_hour is 'Clock hour of the entry, an integer 0-23; the session ingest pins it to 0 as a stable per-day slot for the (person, repo, day) dedup.';
comment on column htt.man_hour_entries.source is 'How the entry was recorded; `auto_session` rows are unique per (person, repo, day). Valid values: [auto_session, manual].';
comment on column htt.man_hour_entries.description is 'Free-text note describing the work.';
comment on column htt.man_hour_entries.rate_cents is 'Optional billing rate in cents applied to the hours.';
comment on column htt.man_hour_entries.currency is 'Currency code for `rate_cents`; defaults to `AUD`.';
comment on column htt.man_hour_entries.status is 'Billing lifecycle state. Valid values: [recorded, approved, invoiced, paid, excluded].';
comment on column htt.man_hour_entries.started_at is 'Precise client-provided git-pull instant that started the session; source of the duration metric (PR timestamp minus this); null for legacy rows and contributes 0.';
comment on column htt.man_hour_entries.created_by is 'Audit label (text) of who or what created the row.';
comment on column htt.man_hour_entries.created_at is 'Row creation time.';
comment on column htt.man_hour_entries.updated_at is 'Last modification time.';

comment on table htt.repos is 'One row is: one tracked repository, internal or client-owned. [master · Assets & code | tier 2 stage engine | active]';
comment on column htt.repos.id is 'Primary key.';
comment on column htt.repos.ai_program_id is 'FK to company_os.ai_programs; the tracked repo is 1:1 (unique) with an AI program, its edge8-side identity.';
comment on column htt.repos.company_id is 'FK to company_os.companies; denormalized owning-company scope used for RLS-style filtering and rollups.';
comment on column htt.repos.slug is 'URL slug, unique per company when set; backfilled as kebab-case of `name` for slug-based repo lookups.';
comment on column htt.repos.name is 'Display name of the tracked repo/engagement.';
comment on column htt.repos.github_repo is 'GitHub `owner/name` the sync and telemetry ingest resolve against; unique when set.';
comment on column htt.repos.github_repo_id is 'Numeric GitHub repository id from the API.';
comment on column htt.repos.github_repo_aliases is 'Historical `owner/name` values (renames, org transfers) that telemetry ingest also matches, so a rename does not orphan past records; explicit per repo, never auto-enrolls.';
comment on column htt.repos.roi_metric_name is 'Name of the repo''s FAST-goal ROI metric.';
comment on column htt.repos.roi_metric_unit is 'Unit of the ROI metric. Valid values: [count, money, percent].';
comment on column htt.repos.roi_metric_baseline is 'ROI metric value before the engagement started.';
comment on column htt.repos.roi_metric_target is 'ROI metric value the engagement aims for.';
comment on column htt.repos.roi_metric_period is 'Reporting period of the ROI metric. Valid values: [monthly, quarterly, annual].';
comment on column htt.repos.started_at is 'Engagement lifecycle start instant.';
comment on column htt.repos.ended_at is 'Engagement lifecycle end instant.';
comment on column htt.repos.status is 'Engagement lifecycle state. Valid values: [planned, active, ramping, paused, complete, archived].';
comment on column htt.repos.last_synced_at is 'Most recent PR `updated_at` seen by the GitHub PR sync; advanced after each upsert batch.';
comment on column htt.repos.live_url is 'Live site URL mirrored from the GitHub repo homepage field during PR sync; null when the repo has no homepage set.';
comment on column htt.repos.created_by is 'Audit label (text) of who or what created the row; the tracker''s auth.users linkage was dropped in the edge8 port.';
comment on column htt.repos.created_at is 'Row creation time.';
comment on column htt.repos.updated_at is 'Last modification time.';

comment on table htt.token_allocations is 'One row is: one allotment of tokens to a client engagement — the "allotted" side of burnt/allotted/unburnt. [other · System config & plumbing | tier 2 stage engine | active]';
comment on column htt.token_allocations.id is 'Primary key.';
comment on column htt.token_allocations.seq is 'Monotonic identity sequence; the table is append-only and the current allocation is the highest-seq row per company, unambiguous even when `set_at` ties.';
comment on column htt.token_allocations.company_id is 'FK to companies; the client company whose allotted token pack this row sets.';
comment on column htt.token_allocations.tokens is 'Allotted pack size in tokens (numeric so tenths are possible; UI shows whole); null on the latest row means the pack was removed.';
comment on column htt.token_allocations.set_by_email is 'Email of the Edge8-internal user who set the value, taken from the verified session, never typed input.';
comment on column htt.token_allocations.set_at is 'When this allocation row was recorded.';

comment on table htt.client_identities is 'One row is: one mapping from a tracker client to identifying handles (GitHub org, names) used by the sync. [master · Customers & partners | tier 2 stage engine | active]';
comment on column htt.client_identities.id is 'Primary key.';
comment on column htt.client_identities.repo_id is 'FK to htt.repos; scope of the identity row; null applies the identity to every repo (global).';
comment on column htt.client_identities.git_email is 'Client/owner git commit email; matched case-insensitively to exclude owner commits from attribution and to classify self-reported effort as owner work.';
comment on column htt.client_identities.github_login is 'Client/owner GitHub login; matched case-insensitively against `pull_requests.author_login` to classify a PR as owner (client) rather than Edge8 work.';
comment on column htt.client_identities.label is 'Human-readable label for the identity (who this email/login is).';
comment on column htt.client_identities.created_at is 'Row creation time.';

comment on table company_os.invoices is 'One row is: one invoice mirrored from QuickBooks — QuickBooks is the system of record; this row is for visibility and joins. [transactional · Revenue documents | tier 2 stage engine | active]';
comment on column company_os.invoices.id is 'Primary key.';
comment on column company_os.invoices.company_id is 'FK to companies; the client the invoice bills, mapped from QuickBooks customer ids stored in `companies.metadata` (null when the QBO customer is unmapped, in which case `customer_name` identifies it).';
comment on column company_os.invoices.source is 'Sync source system; currently always `quickbooks` (the table is a read-only QuickBooks mirror, QBO is the source of truth).';
comment on column company_os.invoices.external_id is 'The bare QuickBooks invoice id within its realm; part of the `(source, entity, external_id)` upsert key the sync writes onto.';
comment on column company_os.invoices.doc_number is 'Invoice document number as shown in QuickBooks.';
comment on column company_os.invoices.txn_date is 'Invoice transaction date from QuickBooks.';
comment on column company_os.invoices.due_date is 'Payment due date from QuickBooks; a positive balance past this date derives `overdue` status.';
comment on column company_os.invoices.currency is 'Lowercase ISO currency code of the invoice, default `usd`.';
comment on column company_os.invoices.amount_cents is 'Invoice total in minor units.';
comment on column company_os.invoices.balance_cents is 'Outstanding balance in minor units; zero derives `paid` status.';
comment on column company_os.invoices.status is 'Derived at sync time from the memo, balance, and due date, never stored back to QBO. Valid values: [paid, open, overdue, voided].';
comment on column company_os.invoices.memo is 'QuickBooks private memo field; a `void` marker here derives `voided` status, and the column is never selected in the client portal (privacy hard line).';
comment on column company_os.invoices.payment_link is 'Client-facing pay URL; always null today (no QuickBooks payment-link source is wired up), and the portal omits its Pay button when null.';
comment on column company_os.invoices.lines is 'JSONB array of invoice line items (`description`, `quantity`, `rate`, `amount`, `item_name`) shown to clients in the portal.';
comment on column company_os.invoices.synced_at is 'When the QuickBooks sync last upserted this row.';
comment on column company_os.invoices.created_at is 'Row creation time.';
comment on column company_os.invoices.updated_at is 'Last modification time.';
comment on column company_os.invoices.customer_name is 'QuickBooks customer display name; identifies invoices whose customer has no mapped company.';
comment on column company_os.invoices.entity is 'Which QuickBooks company (realm) the invoice comes from; part of the upsert key because QBO invoice ids are per-realm. Valid values: [edge8, aio].';

comment on table company_os.orders is 'One row is: one Stripe checkout order for a product, with fees, tax, FX, and refunds captured. [transactional · Revenue documents | tier 2 stage engine | active]';
comment on column company_os.orders.id is 'Primary key.';
comment on column company_os.orders.person_id is 'FK to people; the buyer.';
comment on column company_os.orders.product_id is 'FK to products; the product or event ticket tier purchased.';
comment on column company_os.orders.payment_method is 'How payment was taken: `stripe` for checkout orders (Stripe-driven flow), `manual` for admin-recorded roster payments, `offline_vn` in legacy data.';
comment on column company_os.orders.stripe_session_id is 'Stripe Checkout session id stamped at session-create time; the webhook resolves orders by it.';
comment on column company_os.orders.stripe_payment_intent_id is 'Stripe PaymentIntent id, written by the webhook when payment succeeds.';
comment on column company_os.orders.stripe_customer_id is 'Stripe Customer id; not written by any checkout flow in this codebase (carried over from the aio-website order schema).';
comment on column company_os.orders.amount_cents is 'Order total in minor units in the native currency.';
comment on column company_os.orders.tax_cents is 'Tax portion in minor units; written as 0 by the manual roster-payment action.';
comment on column company_os.orders.currency is 'Lowercase ISO currency code of the order.';
comment on column company_os.orders.status is 'Checkout lifecycle, flipped by the Stripe webhook guarded by current status (pending to paid or expired; an expired order can still flip to paid via payment recovery). Valid values: [pending, paid, expired, refunded].';
comment on column company_os.orders.seat_hold_expires_at is 'When the 30-minute Stripe Checkout seat hold for an event registration lapses.';
comment on column company_os.orders.refunded_cents is 'Refunded amount in minor units, shown on the admin orders list.';
comment on column company_os.orders.affiliate_id is 'FK to affiliates; attribution used to mint a commission ledger row when a commission-type code converts.';
comment on column company_os.orders.metadata is 'JSONB context stamped by the checkout flow (e.g. `type` of `event_registration` or `token_pack`, `registration_id`, `token_purchase_id`); the webhook deliberately never overwrites it.';
comment on column company_os.orders.created_at is 'Row creation time.';
comment on column company_os.orders.updated_at is 'Last modification time; doubles as paid-at on the webhook''s status flip.';
comment on column company_os.orders.amount_usd_cents is 'USD-normalized total derived via FX at write time so cross-currency sums are safe; commission gross uses it when set.';
comment on column company_os.orders.stripe_fee_cents is 'Stripe processing fee in minor units; no reads or writes anywhere in this codebase (legacy aio-website column). TODO(owner): confirm whether anything still populates it.';
comment on column company_os.orders.fx_rate is 'Native-to-USD conversion rate; no reads or writes anywhere in this codebase (legacy aio-website column). TODO(owner): confirm whether anything still populates it.';
comment on column company_os.orders.vnd_amount is 'Order amount in Vietnamese dong; no reads or writes anywhere in this codebase (legacy aio-website column for `offline_vn` payments). TODO(owner): confirm whether anything still populates it.';

