comment on column company_os.subscriptions.id is 'Primary key.';
comment on column company_os.subscriptions.person_id is 'FK to people; the subscriber.';
comment on column company_os.subscriptions.product_id is 'FK to products; the recurring product subscribed to.';
comment on column company_os.subscriptions.stripe_customer_id is 'Stripe Customer id behind the subscription (Stripe-driven table; currently an empty scaffold with no writer in this codebase).';
comment on column company_os.subscriptions.stripe_subscription_id is 'Stripe Subscription id linking the row to the Stripe object.';
comment on column company_os.subscriptions.status is 'Subscription lifecycle status, Stripe-shaped; no writer exists in this codebase yet.';
comment on column company_os.subscriptions.current_period_end is 'End of the current Stripe billing period.';
comment on column company_os.subscriptions.cancel_at_period_end is 'Whether the subscription is set to cancel at period end instead of renewing.';
comment on column company_os.subscriptions.affiliate_id is 'FK to affiliates; attribution for the referral program.';
comment on column company_os.subscriptions.created_at is 'Row creation time.';
comment on column company_os.subscriptions.updated_at is 'Last modification time.';

comment on table company_os.products is 'One row is: one sellable product or ticket tier, Stripe-linked, optionally tied to an event. [master · Products & offerings | tier 2 stage engine | active]';
comment on column company_os.products.id is 'Primary key.';
comment on column company_os.products.type is 'Product kind; code writes `event` for event ticket tiers, and the `public_retreats` view treats `type = ''event''` rows grouped by `cohort_slug` as public retreats.';
comment on column company_os.products.slug is 'Globally unique URL identifier; event tiers are namespaced under the parent event''s slug with a numeric suffix on collision.';
comment on column company_os.products.title is 'Display name of the product or ticket tier.';
comment on column company_os.products.subtitle is 'Secondary display line under the title; not referenced anywhere in this codebase (legacy catalog field).';
comment on column company_os.products.description is 'Longer description shown on admin product and event tier views.';
comment on column company_os.products.date_start is 'Start date for retreat-style products; shown on the admin products list and in the Infinite Leverage confirmation email.';
comment on column company_os.products.date_end is 'End date for retreat-style products.';
comment on column company_os.products.location is 'Venue or city label for retreat-style products.';
comment on column company_os.products.capacity is 'Per-tier seat cap, independent of the event''s overall capacity.';
comment on column company_os.products.cohort_slug is 'Groups tier products into one retreat cohort; the `public_retreats` view aggregates by it and survey responses are tagged with it.';
comment on column company_os.products.tier is 'Tier identifier within an event or cohort (slugified title with underscores).';
comment on column company_os.products.payment_method_local_vn is 'Whether local Vietnamese payment is offered for the product; not referenced anywhere in this codebase (legacy aio-website flag).';
comment on column company_os.products.stripe_product_id is 'Mirrored Stripe Product id; not read by checkout in this codebase.';
comment on column company_os.products.stripe_price_id is 'Mirrored Stripe Price id; deliberately unused by event checkout, which prices from `amount_cents` via inline `price_data` because mirrored ids may belong to another Stripe account (caio-coach).';
comment on column company_os.products.amount_cents is 'Price in minor units in the native currency; 0 means a free tier that skips Stripe entirely.';
comment on column company_os.products.currency is 'Lowercase ISO currency code of the price.';
comment on column company_os.products.active is 'Whether the product or tier is currently purchasable; inactive tiers are hidden and rejected at registration.';
comment on column company_os.products.created_at is 'Row creation time.';
comment on column company_os.products.updated_at is 'Last modification time.';
comment on column company_os.products.service_line_id is 'FK to service_lines; categorizes the product under a business offering.';
comment on column company_os.products.amount_usd_cents is 'USD-normalized price used for cross-currency display and sorting (admin products list, retreat "from" price).';
comment on column company_os.products.event_id is 'FK to events; set on `type = ''event''` rows to mark the tier as belonging to that event.';
comment on column company_os.products.sort_order is 'Display order of tiers within an event.';

