comment on column company_os.service_lines.description is 'What the offering covers.';
comment on column company_os.service_lines.active is 'Whether the service line is currently offered.';
comment on column company_os.service_lines.created_at is 'Row creation time.';

comment on table company_os.fx_rates is 'One row is: one currency''s current rate to USD. [master · Reference & rules | tier 2 stage engine | active]';
